UPDATE psi_stock.stock SET available_quantity = available_quantity - CASE
WHEN warehouse_code = #{item.warehouseCode} AND sku_code = #{item.skuCode} THEN #{item.quantity}
ELSE 0 END, locked_quantity = locked_quantity + CASE
WHEN warehouse_code = #{item.warehouseCode} AND sku_code = #{item.skuCode} THEN #{item.quantity}
ELSE 0 END WHERE (warehouse_code, sku_code) IN
(#{item.warehouseCode}, #{item.skuCode})
AND (
(warehouse_code = #{item.warehouseCode} AND sku_code = #{item.skuCode} AND available_quantity >= #{item.quantity})
)

UPDATE psi_stock.stock SET quantity = quantity - CASE
WHEN warehouse_code = #{item.warehouseCode} AND sku_code = #{item.skuCode} THEN #{item.quantity}
ELSE 0 END, available_quantity = available_quantity - CASE
WHEN warehouse_code = #{item.warehouseCode} AND sku_code = #{item.skuCode} THEN #{item.quantity}
ELSE 0 END, total_amount = total_amount - (avg_cost_price * CASE
WHEN warehouse_code = #{item.warehouseCode} AND sku_code = #{item.skuCode} THEN #{item.quantity}
ELSE 0 END) WHERE (warehouse_code, sku_code) IN
(#{item.warehouseCode}, #{item.skuCode})
AND (
(warehouse_code = #{item.warehouseCode} AND sku_code = #{item.skuCode} AND available_quantity >= #{item.quantity})
)

